-- BierKompas: agenda (103 evenementen) en nieuws (89 berichten) uit de
-- Stichting Erfgoed Nederlandse Biercultuur. Dezelfde gegevens als de knop
-- "Data-imports" in het admin-paneel, maar dan direct in Supabase te draaien.
-- Uitvoeren via het Supabase-dashboard: SQL Editor -> New query -> plak dit
-- bestand -> Run. Vereist setup_alles_in_een.sql (of add_external_content_imports.sql).
-- Veilig om opnieuw te draaien: bestaande regels worden bijgewerkt.
--
-- Evenementen worden op naam van de eerste beheerder gezet en meteen
-- goedgekeurd, net als bij de import via het admin-paneel.

do $mig$
begin
    if not exists (select 1 from public.profiles where is_admin) then
        raise exception 'Er is nog geen beheerder (profiles.is_admin = true). Maak eerst een beheerder aan.';
    end if;
end;
$mig$;

-- 1. Agenda
insert into public.events (
    bron, bron_id, bron_url, name, event_type, start_date, end_date,
    location_name, street, house_number, postal_code, city, description,
    user_id, status, approved_at, approved_by,
    ticket_regular, ticket_beer, ticket_vip, price, price_incl_btw, price_excl_btw
)
select
    x.bron, x.bron_id, x.bron_url, x.name, x.event_type, x.start_date, x.end_date,
    x.location_name, coalesce(x.street, ''), coalesce(x.house_number, ''), coalesce(x.postal_code, ''), x.city, x.description,
    a.id, 'approved', now(), a.id,
    false, false, false, 0, true, false
