k alle details op de bron: https://www.nederlandsebiercultuur.nl/databank/brouwerij/9885"}, {"bron": "nederlandsebiercultuur", "bron_id": "9896", "bron_url": "https://www.nederlandsebiercultuur.nl/databank/brouwerij/9896", "name": "Beer & Burgers Autumn Edition 2026", "event_type": "Bierfestival", "start_date": "2026-10-31T00:00:00", "end_date": "2026-10-31T23:59:00", "location_name": "Markthal Brandevoort", "street": "De Plaetse", "house_number": "", "postal_code": "5708 ZK", "city": "Helmond", "description": "Bierfestival bij Markthal Brandevoort, Helmond (Noord-Brabant). Bekijk alle details op de bron: https://www.nederlandsebiercultuur.nl/databank/brouwerij/9896"}]$data$::jsonb) as x(
    bron text, bron_id text, bron_url text, name text, event_type text,
    start_date timestamptz, end_date timestamptz, location_name text, street text,
    house_number text, postal_code text, city text, description text
)
cross join (select id from public.profiles where is_admin order by created_at limit 1) a
on conflict (bron, bron_id, start_date) do update set
    bron_url = excluded.bron_url, name = excluded.name, event_type = excluded.event_type,
    end_date = excluded.end_date, location_name = excluded.location_name, street = excluded.street,
    house_number = excluded.house_number, postal_code = excluded.postal_code, city = excluded.city,
    description = excluded.description;

