from jsonb_to_recordset($data$[{"titel": "Ferry Wijnhoven is toegetreden tot het bestuur", "samenvatting": "Dinsdag 29 september 2026 is Ferry WIjnhoven toegetreden tot het bestuur van Stichting Erfgoed Nederlandse Biercultuur. Hij vervult de rol van vice-voorzitter en zal in het nieuwe bestuursjaar Jan Ausems gaan opvolgen als voorzitter. Een…", "inhoud": "Dinsdag 29 september 2026 is Ferry WIjnhoven toegetreden tot het bestuur van Stichting Erfgoed Nederlandse Biercultuur. Hij vervult de rol van vice-voorzitter en zal in het nieuwe bestuursjaar Jan Ausems gaan opvolgen als voorzitter. Een…\n\nLees het volledige bericht bij de bron (Stichting Erfgoed Nederlandse Biercultuur).", "foto_url": null, "status": "gepubliceerd", "gepubliceerd_op": "2026-10-09T12:00:00", "bron_naam": "Stichting Erfgoed Nederlandse Biercultuur", "bron_url": "https://www.nederlandsebiercultuur.nl/publicaties/nieuws-van-de-stichting/ferry-wijnhoven-is-toegetreden-tot-het-bestuur"}, {"titel": "Nieuwe blog: Bierpassie in Paraguay", "samenvatting": "De nieuwe (gast)blog van Tina Rogers beschrijft de biercultuur in Paraguay, lokale brouwerijen, biertradities en de groeiende passie voor bier. Ook legt ze uit waarom Nederlandse brouwerijen hun bieren zouden kunnen inzenden voor zo’n…", "inhoud": "De nieuwe (gast)blog van Tina Rogers beschrijft de biercultuur in Paraguay, lokale brouwerijen, biertradities en de groeiende passie voor bier. Ook legt ze uit waarom Nederlandse brouwerijen hun bieren zouden kunnen inzenden voor zo’n…\n\nLees het volledige bericht bij de bron (Stichting Erfgoed Nederlandse Biercultuur).", "foto_url": null, "status": "gepubliceerd", "gepubliceerd_op": "2026-10-01T12:00:00", "bron_naam": "Stichting Erfgoed Nederlandse Biercultuur", "bron_url": "https://www.nederlandsebiercultuur.nl/publicaties/nieuws-van-de-stichting/nieuwe-blog-bierpassie-in-paraguay"}, {"titel": "Weer een petitie?", "samenvatting": "🤨 WEER EEN PETITIE? 🍺 Ja, alweer. En weer om iets belangrijks te redden: j